// 1. On récupère les données
const itemsBD = $items("BD");
const itemsRomans = $items("Roman");

let stats = {
  mangas: { tomes: 0 },
  comics: { tomes: 0 },
  bd: { tomes: 0 },
  romans: { series: 0 }
};

// 2. Traitement des BD (On somme les albums possédés)
itemsBD.forEach(item => {
  const data = item.json;
  const status = (data.statut || "").toLowerCase();

  // FILTRE STRICT : On vérifie que ça commence par "possédé" 
  // pour éviter de compter les "Non possédé"
  if (status.startsWith("possédé")) {
    const cat = (data.categorie || "").toLowerCase();
    const nbTomes = parseInt(data.albums_possedes) || 0;

    if (cat.includes("manga")) {
      stats.mangas.tomes += nbTomes;
    } else if (cat.includes("comic")) {
      stats.comics.tomes += nbTomes;
    } else {
      stats.bd.tomes += nbTomes;
    }
  }
});

// 3. Traitement des Romans (On compte les lignes possédées)
const romansPossedes = itemsRomans.filter(item => {
  const status = (item.json.statut || "").toLowerCase();
  // Même filtre strict ici
  return status.startsWith("possédé");
});
stats.romans.series = romansPossedes.length;

// 4. Calculs finaux
const totalBD = stats.mangas.tomes + stats.comics.tomes + stats.bd.tomes;
const totalGlobal = totalBD + stats.romans.series;

const pcBD = totalGlobal > 0 ? Math.round((totalBD / totalGlobal) * 100) : 0;
const pcRomans = totalGlobal > 0 ? Math.round((stats.romans.series / totalGlobal) * 100) : 0;

// 5. Formatage de la réponse
const phrase = `Tu possèdes un total de ${totalGlobal} livres : ${stats.mangas.tomes} Mangas, ${stats.comics.tomes} Comics, ${stats.bd.tomes} BD et ${stats.romans.series} Romans. Cela représente environ ${pcBD}% pour les BD et ${pcRomans}% pour les romans.`;

return [{
  json: {
    total_bd: totalBD,
    detail: stats,
    phrase_reponse: phrase
  }
}];
